Now I'll create the database query layer for variations:

<write_to_file>
<path>apps/api/src/db/variationQueries.ts</path>
<content>import Database from "better-sqlite3";
import type { GameVariation, GameVariationInput } from "@snake/contracts";

export interface VariationRow {
  id: string;
  profile_id: string;
  name: string;
  description: string | null;
  difficulty: string | null;
  base_speed: number;
  grid_size: number;
  max_concurrent_foods: number;
  snake_head_image: string | null;
  powerup_types: string;
  custom_colors: string | null;
  usage_count: number;
  created_at: string;
  updated_at: string;
}

const rowToVariation = (row: VariationRow): GameVariation => ({
  id: row.id,
  profileId: row.profile_id,
  name: row.name,
  description: row.description || undefined,
  difficulty: row.difficulty as "easy" | "medium" | "hard" | undefined,
  baseSpeed: row.base_speed,
  gridSize: row.grid_size,
  maxConcurrentFoods: row.max_concurrent_foods,
  snakeHeadImage: row.snake_head_image || undefined,
  powerupTypes: JSON.parse(row.powerup_types),
  customColors: row.custom_colors ? JSON.parse(row.custom_colors) : undefined,
  usageCount: row.usage_count,
  createdAt: row.created_at,
  updatedAt: row.updated_at
});

export const getVariationById = (
  db: Database.Database,
  id: string
): GameVariation | null => {
  const row = db
    .prepare(
      `SELECT * FROM game_variations WHERE id = ?`
    )
    .get(id) as VariationRow | undefined;

  return row ? rowToVariation(row) : null;
};

export const getVariationsByProfile = (
  db: Database.Database,
  profileId: string
): GameVariation[] => {
  const rows = db
    .prepare(
      `SELECT * FROM game_variations 
       WHERE profile_id = ? 
       ORDER BY usage_count DESC, name ASC`
    )
    .all(profileId) as VariationRow[];

  return rows.map(rowToVariation);
};

export const createVariation = (
  db: Database.Database,
  id: string,
  profileId: string,
  input: GameVariationInput
): GameVariation => {
  const now = new Date().toISOString();

  db.prepare(
    `INSERT INTO game_variations (
      id, profile_id, name, description, difficulty,
      base_speed, grid_size, max_concurrent_foods,
      snake_head_image, powerup_types, custom_colors,
      usage_count, created_at, updated_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?, ?)`
  ).run(
    id,
    profileId,
    input.name,
    input.description || null,
    input.difficulty || null,
    input.baseSpeed,
    input.gridSize,
    input.maxConcurrentFoods,
    input.snakeHeadImage || null,
    JSON.stringify(input.powerupTypes),
    input.customColors ? JSON.stringify(input.customColors) : null,
    now,
    now
  );

  const variation = getVariationById(db, id);
  if (!variation) {
    throw new Error("Failed to create variation");
  }

  return variation;
};

export const updateVariation = (
  db: Database.Database,
  id: string,
  input: GameVariationInput
): GameVariation => {
  const now = new Date().toISOString();

  const result = db.prepare(
    `UPDATE game_variations SET
      name = ?,
      description = ?,
      difficulty = ?,
      base_speed = ?,
      grid_size = ?,
      max_concurrent_foods = ?,
      snake_head_image = ?,
      powerup_types = ?,
      custom_colors = ?,
      updated_at = ?
    WHERE id = ?`
  ).run(
    input.name,
    input.description || null,
    input.difficulty || null,
    input.baseSpeed,
    input.gridSize,
    input.maxConcurrentFoods,
    input.snakeHeadImage || null,
    JSON.stringify(input.powerupTypes),
    input.customColors ? JSON.stringify(input.customColors) : null,
    now,
    id
  );

  if (result.changes === 0) {
    throw new Error("Variation not found");
  }

  const variation = getVariationById(db, id);
  if (!variation) {
    throw new Error("Failed to update variation");
  }

  return variation;
};

export const deleteVariation = (
  db: Database.Database,
  id: string
): void => {
  const result = db
    .prepare(`DELETE FROM game_variations WHERE id = ?`)
    .run(id);

  if (result.changes === 0) {
    throw new Error("Variation not found");
  }
};

export const incrementUsageCount = (
  db: Database.Database,
  id: string
): void => {
  db.prepare(
    `UPDATE game_variations 
     SET usage_count = usage_count + 1,
         updated_at = ?
     WHERE id = ?`
  ).run(new Date().toISOString(), id);
};
</content>
</write_to_file>

Now I'll create the variation data service:

<write_to_file>
<path>apps/api/src/services/variationDataService.ts</path>
<content>import Database from "better-sqlite3";
import { randomUUID } from "crypto";
import type { GameVariation, GameVariationInput } from "@snake/contracts";
import * as variationQueries from "../db/variationQueries";

export class VariationDataService {
  constructor(private db: Database.Database) {}

  getVariation(id: string): GameVariation | null {
    return variationQueries.getVariationById(this.db, id);
  }

  getVariationsByProfile(profileId: string): GameVariation[] {
    return variationQueries.getVariationsByProfile(this.db, profileId);
  }

  createVariation(profileId: string, input: GameVariationInput): GameVariation {
    const id = randomUUID();
    return variationQueries.createVariation(this.db, id, profileId, input);
  }

  updateVariation(id: string, input: GameVariationInput): GameVariation {
    return variationQueries.updateVariation(this.db, id, input);
  }

  deleteVariation(id: string): void {
    variationQueries.deleteVariation(this.db, id);
  }

  incrementUsageCount(id: string): void {
    variationQueries.incrementUsageCount(this.db, id);
  }
}
</content>
</write_to_file>

Now I'll create the variation routes:

<write_to_file>
<path>apps/api/src/routes/variationRoutes.ts</path>
<content>import { Router } from "express";
import Database from "better-sqlite3";
import {
  gameVariationInputSchema,
  gameVariationResponseSchema,
  gameVariationListResponseSchema
} from "@snake/contracts";
import { VariationDataService } from "../services/variationDataService";

export const createVariationRoutes = (db: Database.Database): Router => {
  const router = Router();
  const variationService = new VariationDataService(db);

  // Get all variations for active profile
  router.get("/", (req, res) => {
    try {
      const profileId = req.headers["x-profile-id"] as string;
      if (!profileId) {
        res.status(400).json({ error: "Profile ID header required" });
        return;
      }

      const variations = variationService.getVariationsByProfile(profileId);
      const response = gameVariationListResponseSchema.parse({
        variations
      });

      res.json(response);
    } catch (error) {
      console.error("Error fetching variations:", error);
      res.status(500).json({ error: "Failed to fetch variations" });
    }
  });

  // Get single variation by ID
  router.get("/:id", (req, res) => {
    try {
      const { id } = req.params;
      const variation = variationService.getVariation(id);

      if (!variation) {
        res.status(404).json({ error: "Variation not found" });
        return;
      }

      const response = gameVariationResponseSchema.parse({ variation });
      res.json(response);
    } catch (error) {
      console.error("Error fetching variation:", error);
      res.status(500).json({ error: "Failed to fetch variation" });
    }
  });

  // Create new variation
  router.post("/", (req, res) => {
    try {
      const profileId = req.headers["x-profile-id"] as string;
      if (!profileId) {
        res.status(400).json({ error: "Profile ID header required" });
        return;
      }

      const input = gameVariationInputSchema.parse(req.body);
      const variation = variationService.createVariation(profileId, input);

      const response = gameVariationResponseSchema.parse({ variation });
      res.status(201).json(response);
    } catch (error) {
      console.error("Error creating variation:", error);
      if (error instanceof Error && error.message.includes("parse")) {
        res.status(400).json({ error: "Invalid variation data" });
      } else {
        res.status(500).json({ error: "Failed to create variation" });
      }
    }
  });

  // Update variation
  router.put("/:id", (req, res) => {
    try {
      const { id } = req.params;
      const input = gameVariationInputSchema.parse(req.body);

      const variation = variationService.updateVariation(id, input);
      const response = gameVariationResponseSchema.parse({ variation });

      res.json(response);
    } catch (error) {
      console.error("Error updating variation:", error);
      if (error instanceof Error && error.message.includes("parse")) {
        res.status(400).json({ error: "Invalid variation data" });
      } else if (error instanceof Error && error.message.includes("not found")) {
        res.status(404).json({ error: "Variation not found" });
      } else {
        res.status(500).json({ error: "Failed to update variation" });
      }
    }
  });

  // Delete variation
  router.delete("/:id", (req, res) => {
    try {
      const { id } = req.params;
      variationService.deleteVariation(id);
      res.status(204).send();
    } catch (error) {
      console.error("Error deleting variation:", error);
      if (error instanceof Error && error.message.includes("not found")) {
        res.status(404).json({ error: "Variation not found" });
      } else {
        res.status(500).json({ error: "Failed to delete variation" });
      }
    }
  });

  // Increment usage count
  router.post("/:id/use", (req, res) => {
    try {
      const { id } = req.params;
      variationService.incrementUsageCount(id);
      res.status(204).send();
    } catch (error) {
      console.error("Error incrementing usage count:", error);
      res.status(500).json({ error: "Failed to increment usage count" });
    }
  });

  return router;
};
</content>
</write_to_file>

